ATOM WINAPI AddAtomW( LPCWSTR str )
{
    ATOM                atom = 0;
    RTL_ATOM_TABLE      table;

    if (!check_integral_atom( str, &atom ) && (table = get_local_table( 0 )))
    {
        if (!set_ntstatus( RtlAddAtomToAtomTable( table, str, &atom ))) return 0;
    }
    return atom;
}

